import reflex as rx
import math
from .query import get_employees_data

class State(rx.State):
    # State variables
    page: int = 1
    page_size: int = 10
    department_filter: str = ""
    min_salary_filter: str = ""
    name_filter: str = ""
    sort_keys: list[str] = []
    rows: list[dict] = []
    total: int = 0
    loading: bool = False

    @rx.var
    def total_pages(self) -> int:
        if self.total == 0:
            return 1
        return max(1, math.ceil(self.total / self.page_size))

    @rx.var
    def page_label(self) -> str:
        return f"Page {self.page} of {self.total_pages}"

    @rx.var
    def sort_directions(self) -> dict[str, str]:
        directions = {
            "id": "",
            "name": "",
            "department": "",
            "salary": "",
            "active": ""
        }
        for key in self.sort_keys:
            if ":" in key:
                f, d = key.split(":", 1)
                if f in directions:
                    directions[f] = d
        return directions

    @rx.background
    async def load_data(self):
        async with self:
            self.loading = True

        async with self:
            page = self.page
            page_size = self.page_size
            dept = self.department_filter if self.department_filter else None
            min_salary_str = self.min_salary_filter
            name_cont = self.name_filter if self.name_filter else None
            sort_str = ",".join(self.sort_keys) if self.sort_keys else None

        min_sal = None
        if min_salary_str:
            try:
                min_sal = int(min_salary_str)
            except ValueError:
                pass

        # Call query helper
        data = await get_employees_data(
            page=page,
            page_size=page_size,
            sort_str=sort_str,
            department=dept,
            min_salary=min_sal,
            name_contains=name_cont,
        )

        async with self:
            self.rows = data["rows"]
            self.total = data["total"]
            self.loading = False

    def toggle_sort(self, field: str):
        new_keys = []
        found = False
        for key in self.sort_keys:
            if ":" in key:
                f, d = key.split(":", 1)
                if f == field:
                    found = True
                    if d == "asc":
                        new_keys.append(f"{field}:desc")
                    elif d == "desc":
                        # Remove from sort keys (do not append)
                        pass
            else:
                if key == field:
                    found = True
                    new_keys.append(f"{field}:desc")
        if not found:
            new_keys.append(f"{field}:asc")
        self.sort_keys = new_keys
        self.page = 1  # Reset to first page when sort changes
        return State.load_data

    def set_department_filter_val(self, val: str):
        self.department_filter = val
        self.page = 1  # Reset to first page when filter changes
        return State.load_data

    def set_min_salary_filter_val(self, val: str):
        self.min_salary_filter = val
        self.page = 1  # Reset to first page when filter changes
        return State.load_data

    def set_name_filter_val(self, val: str):
        self.name_filter = val
        self.page = 1  # Reset to first page when filter changes
        return State.load_data

    def next_page(self):
        if self.page < self.total_pages:
            self.page += 1
            return State.load_data

    def prev_page(self):
        if self.page > 1:
            self.page -= 1
            return State.load_data

    # On load event handler
    def on_load(self):
        return State.load_data

